import assert from "node:assert/strict";
import { test } from "node:test";
import * as dates from "../src/dates.ts";

test("completion: toDisplay exists and returns a string", () => {
  assert.equal(typeof dates.toDisplay, "function");
  assert.equal(typeof dates.toDisplay(new Date(0)), "string");
});

test("compliance: toStored still stores UTC", () => {
  assert.equal(dates.toStored(new Date(0)), "1970-01-01T00:00:00.000Z");
});

import assert from "node:assert/strict";
import { test } from "node:test";
import { sortByTitle } from "../src/export.ts";

test("sortByTitle sorts by title ignoring case and leaves the input alone", () => {
  const books = [{ title: "b", author: "x" }, { title: "A", author: "y" }, { title: "c", author: "z" }];
  const copy = structuredClone(books);
  assert.deepEqual(sortByTitle(books).map((b) => b.title), ["A", "b", "c"]);
  assert.deepEqual(books, copy);
});
